package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code householdMemberCount}: the number of owners in this owner's household
 * (owners sharing the same {@code householdId}) counting this new owner, i.e. the size of the
 * household immediately after this create.
 *
 * <p>Runs after {@link AssignHouseholdId} has set the shared {@code householdId} and before
 * {@link SaveOwner}, within the same write transaction. It counts the owners persisted so far that
 * share this owner's householdId and adds one for this new, not-yet-saved owner, so the value
 * reflects the household size after this create.
 */
public class AssignHouseholdMemberCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        int count = 1; // this new owner, not yet persisted
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId != null && householdId.equals(existing.getHouseholdId())) {
                count++;
            }
        }
        owner.setHouseholdMemberCount(count);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's {@code householdId}: a stable identifier shared by all owners who live in the
 * same household, i.e. share a last name and postcode. It is derived from the normalized last name and
 * postcode (see {@link OwnerIdentity#householdId}), so two owners in the same household
 * deterministically receive the same value without any lookup — the household is computed, never linked.
 *
 * <p>Runs after {@link BuildOwner} has mapped the request onto the entity and before
 * {@link SaveOwner}, so the assigned id is persisted and returned. It also feeds the derived
 * {@code identityKey} that {@link CheckIdentityUnique} uses for duplicate detection.
 */
public class AssignHouseholdId {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(OwnerIdentity.householdId(owner.getLastName(), owner.getPostcode()));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code namesakeCount}: the number of existing owners (before this create)
 * sharing the same firstName and lastName, compared case-insensitively.
 *
 * <p>Runs after {@link BuildOwner} has mapped the request onto the entity and before
 * {@link SaveOwner}, within the same write transaction; it counts the owners persisted so far
 * (excluding this new, not-yet-saved one), so the value reflects the state immediately before the
 * insert.
 */
public class AssignNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (equalsIgnoreCase(firstName, existing.getFirstName())
                    && equalsIgnoreCase(lastName, existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    private static boolean equalsIgnoreCase(String a, String b) {
        return a == null ? b == null : a.equalsIgnoreCase(b);
    }
}

